import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../providers/cart_provider.dart'; import 'checkout_screen.dart';
class CartScreen extends StatelessWidget{const CartScreen({super.key});@override Widget build(BuildContext c){final cart=c.watch<CartProvider>();return Scaffold(appBar:AppBar(title:const Text('Cart',style:TextStyle(fontWeight:FontWeight.w900))),body:cart.items.isEmpty?Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:90,height:90,decoration:BoxDecoration(color:const Color(0xffe7f6ee),borderRadius:BorderRadius.circular(30)),child:const Icon(Icons.shopping_bag_outlined,size:44,color:Color(0xff0b7a53))),const SizedBox(height:15),const Text('Your cart is empty',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:6),const Text('Add products you love to continue.')])):Column(children:[Expanded(child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:cart.items.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i){final x=cart.items[i];return Card(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Container(width:76,height:76,decoration:BoxDecoration(color:const Color(0xfff1f4f2),borderRadius:BorderRadius.circular(12)),child:Image.asset(x.product.imageAsset,fit:BoxFit.contain)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(x.product.name,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w800)),Text(x.product.unit,style:TextStyle(color:Colors.grey.shade600,fontSize:12)),const SizedBox(height:6),Text('₹${x.product.sellingPrice.round()}',style:const TextStyle(fontWeight:FontWeight.w900))])),IconButton(onPressed:()=>cart.remove(x.product),icon:const Icon(Icons.remove_circle_outline)),Text('${x.quantity}',style:const TextStyle(fontWeight:FontWeight.w900)),IconButton(onPressed:()=>cart.add(x.product),icon:const Icon(Icons.add_circle_outline))])))})),Container(padding:const EdgeInsets.fromLTRB(18,15,18,18),decoration:const BoxDecoration(color:Colors.white),child:Column(children:[_Row('Subtotal',true),_Row('Delivery',false),const Divider(),_TotalRow(),const SizedBox(height:12),SizedBox(width:double.infinity,height:52,child:Builder(builder:(ctx)=>FilledButton(onPressed:()=>Navigator.push(ctx,MaterialPageRoute(builder:(_)=>const CheckoutScreen())),child:Text('Continue • ₹${cart.total.round()}'))))]))]);}}
class _Row extends StatelessWidget{final String name;final bool sub;const _Row(this.name,this.sub);@override Widget build(BuildContext c){final cart=c.read<CartProvider>();final value=name=='Subtotal'?cart.subtotal:cart.delivery;return Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Row(children:[Text(name),const Spacer(),Text('₹${value.round()}')]));}}
